import unittest
import deposit_amount as app

class Behavior(unittest.TestCase):
    def test_exact_cents(self):
        for text, cents in [('0.29', 29), ('1.13', 113), ('4.56', 456), ('18.99', 1899), ('0.01', 1), ('0.00', 0), ('12.00', 1200)]:
            with self.subTest(text=text):
                result = app.to_cents(text)
                self.assertEqual(result, cents)
                self.assertIs(type(result), int)
    def test_negative_and_large(self):
        self.assertEqual(app.to_cents('-0.29'), -29)
        self.assertEqual(app.to_cents('-1.13'), -113)
        self.assertEqual(app.to_cents('999999999.99'), 99999999999)
        self.assertEqual(app.to_cents('-0.00'), 0)

if __name__ == '__main__':
    unittest.main()

